fn put64(out:[*]u8,pos:usize,value:i64)void{const u:u64=@bitCast(value);for(0..8)|j|out[pos+j]=@truncate(u>>(8*j));}
pub export fn edn_iir_cascade(raw:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{const v=raw orelse return -1;if(n<2 or n>50)return -1;const count=v[0];var x=v[1];if(count<1 or count>8 or x< -1024 or x>1023 or n!=2+6*@as(usize,@intCast(count)))return -1;const q:usize=@intCast(count);var c=[_]i64{0}**32;var s=[_]i64{0}**16;for(0..4*q)|i|{c[i]=v[2+i];if(c[i]< -1024 or c[i]>1023)return -1;}for(0..2*q)|i|{s[i]=v[2+4*q+i];if(s[i]< -1024 or s[i]>1023)return -1;}const bytes=8*(1+2*q);const o=out orelse return -2;if(cap<bytes)return -2;for(0..q)|i|{const t=x+((c[4*i+2]*s[2*i]+c[4*i+3]*s[2*i+1])>>15);x=t+((c[4*i]*s[2*i]+c[4*i+1]*s[2*i+1])>>15);s[2*i+1]=s[2*i];s[2*i]=t;}put64(o,0,x);for(0..2*q)|i|put64(o,8*(i+1),s[i]);return @intCast(bytes);}
